               <span>SQL</span>
             </label>
           </div>
         </fieldset>
       </div>

       <div class="form-field">
         <fieldset>
           <legend>2. Which languages are commonly used for web development?</legend>
           <div class="choices">
             <label class="choice" for="q2-javascript">
               <input id="q2-javascript" name="question-2" type="checkbox" value="JavaScript">
               <span>JavaScript</span>
             </label>
             <label class="choice" for="q2-css">
               <input id="q2-css" name="question-2" type="checkbox" value="CSS">
               <span>CSS</span>
             </label>
             <label class="choice" for="q2-ruby">
               <input id="q2-ruby" name="question-2" type="checkbox" value="Ruby">
               <span>Ruby</span>
             </label>
             <label class="choice" for="q2-fortran">
               <input id="q2-fortran" name="question-2" type="checkbox" value="Fortran">
               <span>Fortran</span>
             </label>
           </div>
