   <script>
     const form = document.querySelector("#quiz-form");
     const result = document.querySelector("#quiz-result");
     const questionNames = ["question-1", "question-2", "question-3"];

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const unanswered = questionNames.filter((name) => {
         return form.querySelectorAll(`input[name="${name}"]:checked`).length === 0;
       });

       result.classList.remove("is-success", "is-error");

       if (unanswered.length > 0) {
         result.textContent = "Please choose at least one answer for every question.";
         result.classList.add("is-error");
         form.querySelector(`input[name="${unanswered[0]}"]`).focus();
         return;
       }

       const totalSelected = questionNames.reduce((total, name) => {
         return total + form.querySelectorAll(`input[name="${name}"]:checked`).length;
       }, 0);

       result.textContent = `Quiz submitted with ${totalSelected} selected answer${totalSelected === 1 ? "" : "s"}.`;
       result.classList.add("is-success");
     });
